/** Rank medallion SVG keyed by BOTH level schemes: mobile `lib/levels` keys
 *  (cekirge, rekabet) AND `@tennis/shared` LevelCode (yeni_cekirge, rekabetci). */
export const RANK_SVG: Record<string, string> = {
  cekirge: CEKIRGE,
  caylak: CAYLAK,
  amator: AMATOR,
  rekabet: REKABETCI,
  usta: USTA,
  elit: ELIT,
  sampiyon: SAMPIYON,
  // @tennis/shared LevelCode aliases
  yeni_cekirge: CEKIRGE,
  rekabetci: REKABETCI,
};

/** SVG markup for a level key, '' if unknown. Aspect ratio 320:430. */
export function rankSvg(levelKey: string): string {
  return RANK_SVG[levelKey] ?? '';
}

export const RANK_ASPECT = 430 / 320;
